coach='<section class="section shell coach-section" data-coach hidden></section>'
home='''<section class="hero"><img class="hero-image" src="./assets/peakform-hero.jpg" alt="" width="1200" height="1800" fetchpriority="high"><div class="hero-shade"></div><div class="shell hero-content"><p class="eyebrow">PEAKFORM TRAINING</p><h1 data-setting="heroTitle">최고의 순간을 위한,<br>나만의 움직임.</h1><p class="hero-desc" data-setting="heroDescription">선수의 경기력부터 일상의 움직임까지.<br>시즌과 몸의 상태를 함께 살피는 피크폼 트레이닝 시스템.</p><div class="hero-actions">'''+link('./programs.html','프로그램 살펴보기','button mint')+link('./about.html','피크폼 알아보기','text-link')+'''</div><div class="hero-bottom"><span>REACH YOUR PEAK, OWN YOUR FORM</span></div></div><span class="image-credit">이미지 제공 · 피크폼</span></section><div class="discipline-strip"><div class="shell"><span>PERFORMANCE</span><img src="./assets/mark.png" alt="" width="32" height="17"><span>RECOVERY</span><img src="./assets/mark.png" alt="" width="32" height="17"><span>MOVEMENT</span><img src="./assets/mark.png" alt="" width="32" height="17"><span>PEAKFORM</span></div></div><section class="section shell approach" id="approach"><div>'''+heading('THE PEAKFORM APPROACH','몸을 이해하고,<br>목표에 맞게 움직입니다.')+'''</div><div class="approach-copy"><p>최고의 퍼포먼스에 도달하는 것.<br>그리고 스스로의 폼을 갖는 것.</p><p>피크폼은 시즌의 경기력과 매일의 움직임을 함께 봅니다. 현재의 기능과 컨디션을 확인하고, 필요한 훈련과 회복을 연결합니다.</p>'''+link('./system.html','트레이닝 시스템 보기','text-link dark')+'''</div></section><section class="section program-section"><div class="shell"><div class="section-title-row">'''+heading('FIND YOUR PROGRAM','지금 나에게 필요한 트레이닝.')+link('./programs.html','전체 프로그램','text-link dark')+'''</div><div class="program-grid">'''+cards+'''</div></div></section><section class="section shell"><div class="section-title-row">'''+heading('TRAIN WITH YOUR SEASON','시즌이 달라지면,<br>훈련의 목적도 달라집니다.','시즌 계획과 경기 일정에 맞춰 훈련의 강도와 양을 조절합니다.')+'''<p class="side-note">한 번의 기록을 넘어,<br>시즌 전체의 경기력을 생각합니다.</p></div>'''+seasons()+'''</section><section class="space-preview"><div class="space-art"><div class="floor-drawing" aria-hidden="true"><span class="zone a">PERFORMANCE</span><span class="zone b">STRENGTH</span><span class="zone c">RECOVERY</span><span class="zone d">MOVEMENT</span><span class="drawing-axis">PEAKFORM / SPACE SYSTEM</span></div><span class="art-caption">공간 운영 개념도</span></div><div class="space-copy">'''+heading('TWO FLOORS, ONE SYSTEM','훈련에서 회복까지.<br>하나의 흐름으로.')+'''<div class="floor-row"><strong>1F</strong><div><h3>스포츠 퍼포먼스 존</h3><p>근력 · 파워 · 스피드 · 팀 트레이닝</p></div></div><div class="floor-row"><strong>2F</strong><div><h3>리커버리 존</h3><p>기능 회복 · 보강운동 · 컨디셔닝</p></div></div>'''+link('./space.html','공간 운영 살펴보기','text-link dark')+'''</div></section>'''+coach+'''<section class="section shell"><div class="section-title-row">'''+heading('PEAKFORM JOURNAL','움직임을 쌓는 이야기.')+link('./news/','소식 전체 보기','text-link dark')+'''</div><div data-feed data-limit="3" class="journal-grid"><div class="journal-empty"><p class="eyebrow">OUR NEXT CHAPTER</p><h3>피크폼의 이야기가 이곳에 쌓입니다.</h3><p>트레이닝 현장과 새로운 소식을 전하겠습니다.</p></div></div></section>'''
about=head('ABOUT PEAKFORM','Reach your peak,<br><em>own your form.</em>','자신의 가능성에 도달하고, 오래 지켜갈 수 있는 움직임을 만드는 곳.')+'<section class="section shell split">'+heading('OUR PURPOSE','좋은 움직임이<br>다음 가능성을 만듭니다.')+'<div class="prose"><p>선수에게는 최고의 퍼포먼스와 스스로의 폼을. 일상에서는 신체 기능의 회복과 증진을 통한 건강한 움직임을.</p><p>작은 기능 하나가 전체 움직임을 바꿀 수 있다는 생각에서 피크폼의 트레이닝은 시작됩니다. 현재 상태와 목표를 확인하고, 훈련과 회복을 하나의 계획으로 연결합니다.</p></div></section><section class="section tinted"><div class="shell value-grid">'+''.join(f'<article><span class="big-number">0{i+1}</span><h3>{t}</h3><p>{d}</p></article>' for i,(t,d) in enumerate([('경기력과 회복을 함께','경기력 향상과 부상 예방을 함께 고려하고 안전한 경기 복귀를 지원합니다.'),('시즌 전체를 보는 계획','경기 일정과 개인의 역할을 바탕으로 시즌 동안의 컨디션을 관리합니다.'),('일상까지 이어지는 기능','유연성·가동성·안정성·코어를 바탕으로 지속할 수 있는 운동의 기반을 만듭니다.')]))+'</div></section>'+coach+'<section class="section shell">'+heading('HOW WE WORK','현재를 확인하고, 다음을 계획합니다.')+'<ol class="process">'+''.join(f'<li><span>0{i+1}</span><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate([('목표와 일정 확인','운동 경험, 현재 컨디션, 종목과 시즌 목표를 살핍니다.'),('움직임과 기능 점검','기본 동작과 가동성, 안정성 등 필요한 기능을 확인합니다.'),('맞춤 계획과 훈련','개인 또는 팀의 목적에 맞춰 훈련과 회복을 계획합니다.'),('기록과 조정','반응과 컨디션을 기록하고 시즌 변화에 따라 수정합니다.')]))+'</ol></section>'
programs=head('PROGRAMS','목표는 다르게.<br>기본은 단단하게.','운동 경험과 시즌, 현재 몸의 상태에 맞춰 트레이닝의 시작점을 찾습니다.')+'<div class="shell program-quick">'+''.join(f'<a href="#{p[0]}">{p[2]}</a>' for p in PROGRAMS)+'<a href="#fees" data-pricing hidden>이용요금</a></div><div class="shell">'+''.join(f'<section class="program-detail section" id="{n}"><div><span class="big-number">{n}</span><p class="eyebrow">{en}</p><h2>{title}</h2><p class="intro">{sub}</p></div><div class="prose"><p>{desc}</p><div class="detail-tags">{tags}</div>'+link('./contact.html','이 프로그램 상담 안내','text-link dark')+'</div></section>' for n,en,title,sub,desc,tags in PROGRAMS)+'</div><section id="fees" class="section tinted" data-pricing hidden><div class="shell">'+heading('TRAINING FEES','이용요금 안내','트레이닝 한 회는 50분입니다.')+'<div class="price-table-wrap"><table class="price-table"><caption class="sr-only">피크폼 이용요금</caption><thead><tr><th scope="col">프로그램</th><th scope="col">총 이용금액</th><th scope="col">1회당 금액</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row">{n}회</th><td><span data-setting="price{n}"></span>원</td><td data-unit="{n}"></td></tr>' for n in (1, 10, 20, 30))+'</tbody></table></div><div class="monthly"><div><p class="eyebrow">CONSISTENT MOVEMENT</p><h3>월 무제한</h3><p>주말·공휴일 제외</p></div><strong><span data-setting="priceMonthly"></span><small>원 / 월</small></strong></div><p class="fine-print">적용 대상, 예약 시간, 팀·그룹 이용 조건 등 세부 내용은 상담 시 확인해 주세요.</p></div></section>'
system=head('THE TRAINING SYSTEM','기록 너머,<br>시즌의 경기력으로.','개인의 역할과 출전 시간, 경기 일정을 반영하는 트레이닝 시스템.')+'<section class="section shell">'+heading('SEASON-BASED TRAINING','훈련과 회복을 시즌에 맞춥니다.')+seasons()+'</section><section class="section tinted"><div class="shell">'+heading('INDIVIDUAL WITHIN THE TEAM','같은 팀 안에서도,<br>필요한 훈련은 다릅니다.')+'<div class="two-col">'+''.join(f'<article class="line-card"><p class="eyebrow">{en}</p><h3>{t}</h3><ul>'+''.join(f'<li>{x}</li>' for x in items)+'</ul></article>' for en,t,items in [('HIGH PLAYING TIME','주전 · 출전 시간이 많은 선수',['누적 피로 관리와 회복','보강운동을 통한 부상 예방','컨디셔닝과 경기력 유지','필요에 따른 기능 회복 프로그램 연계']),('BUILDING THE FOUNDATION','후보 · 저학년 선수',['근력과 기초 체력 향상','스피드와 파워 발달','운동기능 향상','시즌 준비를 위한 피지컬 강화'])])+'</div></div></section><section class="section shell split">'+heading('COACHING COLLABORATION','지도진과 함께<br>계획하고 조정합니다.')+'<div class="prose"><p>지도진과 정기적으로 소통하고 훈련 목적에 맞춰 계획을 수립합니다. 선수의 컨디션과 트레이닝 일지를 공유하며 시즌 상황에 따라 프로그램을 수정합니다.</p><p>리커버리, 퍼포먼스, 기능 회복 등 팀에 필요한 목적에 따라 그룹을 나눠 운영합니다.</p></div></section><section class="section shell research-block">'+heading('EVIDENCE & PRACTICE','훈련의 근거를 함께 살핍니다.')+'<div class="two-col"><article><p class="eyebrow">01 / PERIODIZATION</p><h3>준비·경기·회복의 주기</h3><p>훈련은 준비기와 경기기의 목적에 맞춰 계획하고, 강점 유지와 보완의 우선순위를 조절합니다.</p><a href="https://www.nsca.com/education/articles/kinetic-select/application-of-program-design-to-training-seasons/" target="_blank" rel="noopener">NSCA · 시즌별 프로그램 설계 ↗</a></article><article><p class="eyebrow">02 / LOAD & RECOVERY</p><h3>훈련 부하와 회복의 균형</h3><p>훈련량뿐 아니라 경기 부담과 피로·회복 상태를 함께 살피는 관점이 필요합니다.</p><a href="https://www.olympics.com/ioc/documents/athletes/medical-and-scientific-consensus-statements" target="_blank" rel="noopener">IOC · 훈련 부하 관련 합의문 ↗</a></article></div><p class="fine-print">일반적인 훈련 원칙을 설명하는 참고문헌입니다. 기관의 제휴·인증을 의미하지 않습니다.</p></section>'
space=head('THE SPACE','힘을 쌓는 공간.<br>움직임을 되찾는 공간.','훈련의 목적에 따라 연결되는 피크폼 공간 운영 시스템.')+'<section class="section shell"><div class="space-plan">'+''.join(f'<div class="plan-floor {cls}"><span class="floor-label">{f}</span><h2>{title}</h2><div class="plan-grid"><div>{a}</div><div>{b}</div><div class="wide">{c}</div></div></div>' for f,title,cls,a,b,c in [('1F','스포츠 퍼포먼스 존','','STRENGTH<br><strong>근력 · 파워</strong>','SPEED<br><strong>스피드 · 민첩성</strong>','TEAM TRAINING<br><strong>팀 · 그룹 피지컬 트레이닝</strong>'),('2F','리커버리 존','recovery','MOVEMENT<br><strong>보강 · 기능 회복</strong>','CONDITIONING<br><strong>컨디셔닝</strong>','RECOVERY<br><strong>회복 · 스포츠 컨디션 관리</strong>')])+'</div><p class="fine-print">소개자료를 바탕으로 그린 공간 운영 개념도입니다. 실제 시설 사진과 도면은 아닙니다.</p></section><section class="section tinted"><div class="shell">'+heading('CONNECTED ZONES','몸의 상태에 따라 연결되는 기능.')+'<div class="zone-list">'+''.join(f'<div><span>0{i+1}</span><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('피지컬 트레이닝','근력과 파워, 종목에 필요한 움직임 훈련'),('기능 회복','가동성과 안정성, 보강운동'),('카디오','심폐 체력과 컨디셔닝'),('상담 · 대기','목표와 현재 상태를 확인하는 시간'),('외부 활동','트레이닝 계획에 따른 공간 활용')]))+'</div></div></section>'
faq=[('운동 경험이 없어도 시작할 수 있나요?','운동 경험과 현재 상태를 확인한 뒤 기초 움직임부터 계획합니다. 시작 수준은 상담에서 함께 정합니다.'),('팀과 개인 모두 이용할 수 있나요?','개인의 역할에 맞춘 선수 트레이닝과 팀·그룹 트레이닝을 안내합니다. 인원과 종목, 일정에 따른 운영 조건은 상담 시 확인합니다.'),('부상 이후에도 트레이닝할 수 있나요?','현재 가능한 활동 범위와 의료진의 운동 관련 안내를 먼저 확인합니다. 트레이닝은 의료적 진단이나 치료를 대신하지 않습니다.'),('이용요금과 시간은 어떻게 되나요?','트레이닝은 1회 50분입니다. 예약과 이용 조건은 상담 때 안내합니다. <a class="fee-link" data-pricing hidden href="./programs.html#fees">이용요금 보기</a>')]
contact=head('CONTACT PEAKFORM','나에게 맞는 시작점을<br>함께 찾습니다.','선수 트레이닝, 팀 프로그램, 일상 기능 트레이닝에 대해 안내합니다.')+'<section class="section shell split"><div>'+heading('BEFORE WE START','상담 전,<br>이렇게 준비해 주세요.')+'<ol class="contact-list">'+''.join(f'<li><span>0{i+1}</span><div><h3>{t}</h3><p>{d}</p></div></li>' for i,(t,d) in enumerate([('목표와 운동 경험','현재 종목과 운동 경험, 원하는 목표를 정리해 주세요.'),('시즌과 경기 일정','선수·팀은 시즌 계획과 주요 대회 일정을 알려 주세요.'),('현재 컨디션','운동에 영향을 주는 불편함과 가능한 활동 범위를 확인합니다.')]))+'</ol></div><div class="contact-panel"><p class="eyebrow">GET IN TOUCH</p><h2>피크폼 상담 안내</h2><div data-contact><p>상담 채널을 준비하고 있습니다. 먼저 목표에 맞는 프로그램을 살펴보세요.</p><a href="./programs.html">프로그램 보기</a></div></div></section><section class="section shell faq-section">'+heading('FAQ','자주 묻는 질문.')+'<div class="faqs">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faq)+'</div></section>'
news=head('PEAKFORM JOURNAL','움직임의 기록,<br>피크폼의 이야기.','트레이닝 현장과 팀 이야기, 새로운 소식을 전합니다.')+'<section class="section shell journal-section"><div class="journal-toolbar"><div class="filter-tabs" role="group" aria-label="소식 분류">'+''.join(f'<button data-filter="{k}" aria-pressed="{str(k=="all").lower()}" class="'+('active' if k=='all' else '')+f'">{v}</button>' for k,v in [('all','전체'),('notice','공지사항'),('class','트레이닝'),('event','팀 · 현장'),('competition','대회')])+'</div><label class="search-field"><span class="sr-only">소식 검색</span><input type="search" placeholder="이야기 검색" data-search><span aria-hidden="true">⌕</span></label></div><div data-feed class="journal-grid"><div class="journal-empty"><p class="eyebrow">OUR NEXT CHAPTER</p><h2>곧 피크폼의 소식을 전하겠습니다.</h2><p>새로운 트레이닝과 현장 이야기가 이곳에 쌓입니다.</p></div></div></section>'
sources=head('SOURCES & CREDITS','피크폼을 소개하는<br>자료와 출처.','제공된 브랜드 자료와 외부 참고문헌을 구분해 안내합니다.')+'<section class="section shell source-list">'+''.join(f'<article><p class="eyebrow">{en}</p><h2>{title}</h2><p>{desc}</p>'+ (f'<a href="{url}" target="_blank" rel="noopener">자료 보기 ↗</a>' if url else '')+'</article>' for en,title,desc,url in [('PROVIDED MATERIALS','피크폼 소개자료 · 로고 원본','시즌별 훈련과 공간 안내는 피크폼 트레이닝 인천 소개자료를 바탕으로 작성했습니다. 워드마크와 심볼은 피크폼의 원본 로고를 사용합니다.',''),('REFERENCE / NSCA','시즌별 프로그램 설계','Application of Program Design to Training Seasons. 시즌 목적에 따라 훈련을 계획하는 일반적인 원칙을 참고했습니다.','https://www.nsca.com/education/articles/kinetic-select/application-of-program-design-to-training-seasons/'),('REFERENCE / IOC','훈련 부하와 회복','IOC Medical and Scientific Consensus Statements. Load in sport and risk of injury and illness 관련 자료를 참고했습니다.','https://www.olympics.com/ioc/documents/athletes/medical-and-scientific-consensus-statements'),('DESIGN REFERENCE','플리에 홈페이지','소개·프로그램·철학·소식·상담 구성과 GitHub Pages·Google CMS 운영 방식을 참고했습니다. 개인 정보와 게시물은 가져오지 않았습니다.','https://www.plierg.com/'),('PROVIDED IMAGE','홈페이지 배경 이미지','홈페이지 첫 화면에는 피크폼에서 제공한 배경 이미지를 사용합니다.','')])+'</section>'
PAGES={'index.html':('홈','선수의 경기력부터 일상의 움직임까지.',home),'about.html':('피크폼 소개','피크폼의 운영 목적과 트레이닝 방향.',about),'programs.html':('프로그램','피크폼 프로그램과 이용요금.',programs),'system.html':('트레이닝 시스템','시즌과 출전 시간을 반영하는 트레이닝.',system),'space.html':('공간 운영','1층 퍼포먼스와 2층 리커버리 공간 운영.',space),'contact.html':('상담 안내','피크폼 상담 안내와 자주 묻는 질문.',contact),'sources.html':('자료 및 출처','피크폼 제공 자료와 참고문헌.',sources),'news/':('피크폼 소식','트레이닝 현장과 피크폼 소식.',news)}
